CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,phone text NOT NULL,tags jsonb NOT NULL DEFAULT '[]',channels jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,phone));
CREATE TABLE IF NOT EXISTS campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,channel text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'draft',schedule_at timestamptz,delay_ms integer NOT NULL DEFAULT 2000,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS campaign_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,contact_id uuid NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,body text NOT NULL,status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,provider_id text,error text,available_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS campaign_messages_queue_idx ON campaign_messages(status,available_at);
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,contact_id uuid REFERENCES contacts(id) ON DELETE SET NULL,channel text NOT NULL,direction text NOT NULL,external_id text,text text NOT NULL,status text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS messages_user_created_idx ON messages(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,channel text NOT NULL,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_events(id text PRIMARY KEY,user_id uuid REFERENCES users(id) ON DELETE CASCADE,channel text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE SET NULL,action text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
